/* B"H — live scroll covenant polish */
#chat-box{position:relative;scroll-behavior:auto;overscroll-behavior:contain}
#chat-box[data-live-follow="active"]{box-shadow:inset 0 -18px 34px rgba(34,211,238,.045)}
#chat-box[data-live-follow="paused"]::after{
  content:"Live follow paused — use ↓ Live bottom to resume";
  position:sticky;bottom:.65rem;z-index:20;display:block;width:max-content;max-width:calc(100% - 2rem);
  margin:.6rem auto 0;padding:.48rem .78rem;border:1px solid rgba(250,204,21,.35);border-radius:999px;
  background:linear-gradient(135deg,rgba(113,63,18,.88),rgba(2,6,23,.82));color:#fef3c7;font-size:.78rem;font-weight:900;letter-spacing:.02em;
  box-shadow:0 12px 32px rgba(0,0,0,.28),0 0 24px rgba(250,204,21,.12);pointer-events:none;backdrop-filter:blur(10px)
}
.live-follow-button{
  position:absolute;right:1.35rem;bottom:6.25rem;z-index:55;display:none;align-items:center;gap:.45rem;
  padding:.62rem .9rem;border-radius:999px;border:1px solid rgba(34,211,238,.38);
  background:linear-gradient(135deg,rgba(8,47,73,.92),rgba(2,6,23,.9));color:#e0fbff;font-weight:950;letter-spacing:.02em;
  box-shadow:0 18px 50px rgba(0,0,0,.34),0 0 28px rgba(34,211,238,.16);backdrop-filter:blur(14px);cursor:pointer
}
.live-follow-button.is-visible{display:inline-flex;animation:liveFollowPulse 1.7s ease-in-out infinite}
.live-follow-button:hover,.live-follow-button:focus-visible{transform:translateY(-1px);border-color:rgba(125,211,252,.72);box-shadow:0 0 0 3px rgba(34,211,238,.12),0 20px 54px rgba(0,0,0,.38)}
.chat-bottom-sentinel{height:1px;scroll-margin-bottom:1rem}
.message-window-spacer.bottom:not(:disabled){border-style:dashed;box-shadow:0 0 24px rgba(34,211,238,.12)}
@keyframes liveFollowPulse{50%{box-shadow:0 18px 50px rgba(0,0,0,.34),0 0 42px rgba(34,211,238,.28)}}
@media(max-width:760px){#chat-box[data-live-follow="paused"]::after{font-size:.7rem;max-width:calc(100% - 1rem);white-space:normal;text-align:center}.live-follow-button{right:.8rem;bottom:5.25rem;padding:.58rem .78rem;font-size:.84rem}}
